"""Original, code-drawn SVG editorial illustrations; no external news photography."""
from pathlib import Path
import math
out = Path(__file__).resolve().parents[1] / 'public' / 'covers'
styles=[('ai','#fa7649','#7d948f','WORLD MODELS'),('tech','#71b7d3','#a0c1cb','THE NEXT FRONTIER'),('finance','#c4d892','#79895c','FOLLOW THE SIGNAL'),('society','#b9a1d4','#716785','HUMAN CONNECTION'),('culture','#d1af85','#8f7560','A LIVING ARCHIVE'),('art','#e0a1b3','#8c6e8d','BEYOND THE CANVAS')]
for index,(name,accent,sub,label) in enumerate(styles):
    grid=''.join(f'<path d="M{x} 0V900M0 {x}H1400"/>' for x in range(0,1500,70))
    stars=''.join(f'<circle cx="{(i*179+41)%1400}" cy="{(i*113+27)%800}" r="{1 if i%4 else 2}" fill="#c1c5bc" opacity=".3"/>' for i in range(55))
    rings=''.join(f'<ellipse cx="790" cy="390" rx="{r}" ry="{r*.36}" transform="rotate(-32 790 390)"/>' for r in (220,280,345,410,480))
    wires=''.join(f'<path d="M{450+i*27} 650v-65l90-55v-50"/>' for i in range(22))
    faces=''.join(f'<path d="M{650+i*18} {205+i*3}l230 132v250l-230-132z" fill="url(#glass)" stroke="{accent}" stroke-opacity=".15"/>' for i in range(10))
    inner=''.join(f'<ellipse cx="790" cy="350" rx="{r}" ry="{r*.92}" fill="none" stroke="{accent}" stroke-width="1" opacity="{.08+i*.015}"/>' for i,r in enumerate(range(40,162,12)))
    shape = f'<g transform="translate(0 -10)"><path d="M500 390l290-167 290 167-290 167z" fill="#38403c" stroke="#9bafaa" stroke-opacity=".5"/><path d="M500 390v35l290 167v-35z" fill="#171d1d"/><path d="M790 557l290-167v35L790 592z" fill="#3e4b46"/>{faces}<circle cx="790" cy="350" r="165" fill="url(#planet)" filter="url(#shadow)"/>{inner}<ellipse cx="790" cy="350" rx="165" ry="164" fill="none" stroke="url(#rim)" stroke-width="2"/><path d="M678 230q-65 115 10 220" stroke="#fff" opacity=".1" stroke-width="22" fill="none" filter="url(#blur)"/></g>'
    if index==1: shape=f'<g transform="translate(0 -35)"><circle cx="790" cy="400" r="220" fill="url(#planet)"/><ellipse cx="790" cy="400" rx="220" ry="219" fill="none" stroke="url(#rim)" stroke-width="2"/><path d="M440 490q340 150 705-220" stroke="{accent}" stroke-opacity=".45" stroke-width="10" fill="none"/><path d="M440 490q340 150 705-220" stroke="#ddd" stroke-opacity=".8" stroke-width="1" fill="none"/></g>'
    if index==2: shape='<g transform="translate(490 160)">'+''.join(f'<path d="M{i*70} {370-h}l60-35 55 32v{h}l-60 35-55-32z" fill="url(#planet)" stroke="'+accent+f'" stroke-opacity=".5"/><path d="M{i*70} {370-h}l55 32 60-35-55-32z" fill="'+accent+'" fill-opacity=".6"/>' for i,h in enumerate((90,150,220,185,300,370)))+'</g>'
    if index==3: shape='<g>'+''.join(f'<circle cx="{790+math.cos(i*math.pi/4)*190}" cy="{370+math.sin(i*math.pi/4)*170}" r="60" fill="url(#planet)" stroke="{accent}" stroke-opacity=".35"/><path d="M790 370L{790+math.cos(i*math.pi/4)*190} {370+math.sin(i*math.pi/4)*170}" stroke="{accent}" opacity=".3"/>' for i in range(8))+f'<circle cx="790" cy="370" r="100" fill="url(#planet)"/></g>'
    if index==4: shape='<g transform="translate(0 0)">'+''.join(f'<path d="M{600+i*27} {210+i*7}l230 90v300l-230-90z" fill="url(#glass)" stroke="{accent}" stroke-opacity=".5"/>' for i in range(12))+'</g>'
    if index==5: shape=f'<g transform="rotate(-20 790 390)"><rect x="580" y="180" width="420" height="420" rx="100" fill="url(#planet)"/><rect x="660" y="260" width="260" height="260" rx="65" fill="#13191b" stroke="{accent}"/><circle cx="790" cy="390" r="160" fill="none" stroke="{accent}" stroke-opacity=".35" stroke-width="28"/><circle cx="790" cy="390" r="70" fill="url(#planet)"/></g>'
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1400 900"><defs><radialGradient id="bg"><stop stop-color="{sub}" stop-opacity=".3"/><stop offset="1" stop-color="#111719"/></radialGradient><radialGradient id="planet" cx="30%" cy="25%" r="80%"><stop stop-color="#e5d6c1"/><stop offset=".19" stop-color="{accent}"/><stop offset=".55" stop-color="{sub}"/><stop offset=".88" stop-color="#202b2b"/><stop offset="1" stop-color="#0e1516"/></radialGradient><linearGradient id="rim" x2="1" y2="1"><stop stop-color="#f5d9c4"/><stop offset=".5" stop-color="{accent}" stop-opacity=".2"/><stop offset="1" stop-color="{accent}"/></linearGradient><linearGradient id="glass" x2="1" y2="1"><stop stop-color="{sub}" stop-opacity=".08"/><stop offset=".5" stop-color="{accent}" stop-opacity=".04"/><stop offset="1" stop-color="{sub}" stop-opacity=".28"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="20" stdDeviation="35" flood-opacity=".6"/></filter><filter id="blur"><feGaussianBlur stdDeviation="8"/></filter><radialGradient id="vignette"><stop offset=".5" stop-opacity="0"/><stop offset="1" stop-opacity=".65"/></radialGradient><filter id="noise"><feTurbulence type="fractalNoise" baseFrequency=".65" numOctaves="3" stitchTiles="stitch"/></filter></defs><rect width="1400" height="900" fill="#141c1d"/><rect width="1400" height="900" fill="url(#bg)"/><g stroke="#91a8a1" opacity=".045">{grid}</g>{stars}<g fill="none" stroke="{accent}" stroke-opacity=".16" stroke-width="1">{rings}</g><g stroke="{sub}" stroke-opacity=".22" fill="none">{wires}</g>{shape}<text x="68" y="95" fill="#ccd0c7" opacity=".5" font-family="Arial,sans-serif" font-size="12" letter-spacing="5">TECH SWIPE / VISUAL ESSAY</text><path d="M68 120h32M84 104v32" stroke="{accent}" opacity=".7"/><text x="1332" y="98" text-anchor="end" fill="#ccc" opacity=".5" font-family="monospace" font-size="12">TS—0{index+1} / CONCEPT</text><text x="70" y="795" fill="#c4c6b9" opacity=".08" font-family="Arial,sans-serif" font-size="100" font-weight="bold" letter-spacing="-5">{label}</text><rect width="1400" height="900" fill="url(#vignette)"/><rect width="1400" height="900" filter="url(#noise)" opacity=".025"/></svg>'''
    (out/f'{name}.svg').write_text(svg)
